  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not insert on fm.files'
    ELSE '  no   the sign-in''s scopes do not allow insert on fm.files' END; END IF;
