-- fm.folders update parent_id after (line 59): parent.edit or ({parent_id is null} and share)
-- Whether the rule holds for a row: called by the trigger's WHEN, which is kept parsed, as a policy is, so the app
-- role uses it without naming it (authz_int). The row comes as jsonb, read by column name (a partition's columns may
-- be in another order), with the caller's role; the function runs as the owner, reading only that row (sqlutil.from_row)
CREATE FUNCTION authz_int."fm.folders:column parent_id after:holds"(p_row jsonb, authz__role name) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT coalesce((authz_int."folder__edit__has"("folders"."parent_id")
    OR (coalesce((parent_id is null), false)
    AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR (coalesce((inherit), false)
    AND authz_int."folder__share__has"("folders"."parent_id"))))), false) FROM pg_catalog.jsonb_populate_record(NULL::"fm"."folders", p_row) AS "folders"
$f$;

-- checked on the row after the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own; before the update, or after it where the table has a generated column
-- @object trigger "authz_update_after parent_id" ON "fm"."folders"
DO $tr$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = '"fm"."folders"'::pg_catalog.regclass
             AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated <> '') THEN
    EXECUTE 'CREATE TRIGGER "authz_update_after parent_id" AFTER UPDATE ON "fm"."folders" FOR EACH ROW
  WHEN ((OLD."parent_id" IS DISTINCT FROM NEW."parent_id")
    AND pg_catalog.row_security_active(''"fm"."folders"''::pg_catalog.regclass)
    AND NOT authz_int."fm.folders:column parent_id after:holds"(pg_catalog.to_jsonb(NEW), current_user))
  EXECUTE FUNCTION authz_int."fm.folders:column parent_id after"()';
  ELSE
    EXECUTE 'CREATE TRIGGER "authz_update_after parent_id" BEFORE UPDATE ON "fm"."folders" FOR EACH ROW
  WHEN ((OLD."parent_id" IS DISTINCT FROM NEW."parent_id")
    AND pg_catalog.row_security_active(''"fm"."folders"''::pg_catalog.regclass)
    AND NOT authz_int."fm.folders:column parent_id after:holds"(pg_catalog.to_jsonb(NEW), current_user))
  EXECUTE FUNCTION authz_int."fm.folders:column parent_id after"()';
  END IF;
END $tr$;

