CREATE FUNCTION authz_gen."fm.folders:column parent_id:items"(p_row "fm"."folders", authz__role name) RETURNS boolean[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
