REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

DO $gf$
DECLARE f regprocedure;
BEGIN
  FOR f IN SELECT p.oid::regprocedure FROM pg_proc p WHERE p.pronamespace = 'authz_gen'::regnamespace
           AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"fm.file_versions:column id, file_id, object_key, creat_edb04104"', '"fm.file_versions:column id, file_id, object_key, created_by:why"', '"fm.file_versions:delete:items"', '"fm.file_versions:delete:why"', '"fm.file_versions:insert:items"', '"fm.file_versions:insert:refuse"', '"fm.file_versions:insert:why"', '"fm.file_versions:rules:explain"', '"fm.file_versions:update:items"', '"fm.file_versions:update:refuse"', '"fm.file_versions:update:why"', '"fm.files:column folder_id after:items"', '"fm.files:column folder_id after:why"', '"fm.files:column id, owner_id:items"', '"fm.files:column id, owner_id:why"', '"fm.files:column object_key after:items"', '"fm.files:column object_key after:why"', '"fm.files:delete:items"', '"fm.files:delete:why"', '"fm.files:insert:items"', '"fm.files:insert:refuse"', '"fm.files:insert:why"', '"fm.files:rules:explain"', '"fm.files:update:items"', '"fm.files:update:refuse"', '"fm.files:update:why"', '"fm.folders:column id, owner_id, inherit:items"', '"fm.folders:column id, owner_id, inherit:why"', '"fm.folders:column parent_id after:items"', '"fm.folders:column parent_id after:why"', '"fm.folders:column parent_id:items"', '"fm.folders:column parent_id:why"', '"fm.folders:delete:items"', '"fm.folders:delete:why"', '"fm.folders:insert:items"', '"fm.folders:insert:refuse"', '"fm.folders:insert:why"', '"fm.folders:rules:explain"', '"fm.folders:update:items"', '"fm.folders:update:refuse"', '"fm.folders:update:why"', '"fm.group_members:column group_id after:items"', '"fm.group_members:column group_id after:why"', '"fm.group_members:column id, user_id:items"', '"fm.group_members:column id, user_id:why"', '"fm.group_members:delete:items"', '"fm.group_members:delete:why"', '"fm.group_members:insert:items"', '"fm.group_members:insert:refuse"', '"fm.group_members:insert:why"', '"fm.group_members:rules:explain"', '"fm.group_members:update:items"', '"fm.group_members:update:refuse"', '"fm.group_members:update:why"', '"fm.groups:column id, owner_id:items"', '"fm.groups:column id, owner_id:why"', '"fm.groups:column parent_id after:items"', '"fm.groups:column parent_id after:why"', '"fm.groups:delete:items"', '"fm.groups:delete:why"', '"fm.groups:insert:items"', '"fm.groups:insert:refuse"', '"fm.groups:insert:why"', '"fm.groups:rules:explain"', '"fm.groups:update:items"', '"fm.groups:update:refuse"', '"fm.groups:update:why"']::text[]) LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', f, 'fm_app');
  END LOOP;
END $gf$;

